Ordered @($c.field_mask_code) @('title','body','due','reminder_time','completion') 'P0-REMINDER-CATALOGS-001';Ordered @($c.ownership_code) @('service_projection','user_owned','user_authoritative','not_applicable') 'P0-REMINDER-CATALOGS-001'
if(@($c.operation_kind_code|Where-Object{$_-match'^(send|delete|bulk|invite|respond|attendee|generic)$'}).Count-ne 0){Fail 'P0-REMINDER-CATALOGS-001'}

