$perm=Json $PermissionPath 'P0-REMINDER-CROSS-CONTRACT-001';$tw=@($perm.permission_rows|Where-Object{$_.id -eq 'PERM-TODO-WRITE-001'});$tr=@($perm.permission_rows|Where-Object{$_.id -eq 'PERM-TODO-DIAG-001'});if($tw.Count-ne 1-or$tw[0].permission-ne'Tasks.ReadWrite'-or$tw[0].state-ne'disabled'-or$tw[0].advertised-ne$false-or$tr.Count-ne 1-or$tr[0].permission-ne'Tasks.Read'-or$tr[0].kind-ne'graph_delegated_validation_only'){Fail 'P0-REMINDER-TODO-BASELINE-001'}

$op=$m.operation_protocol;Ordered @($op.intent_hmac_input_order) @('operation-key-v1','account_ref','adapter_code','collection_ref','loop_id','source_ref_id_or_none','source_generation','operation_kind_code','canonical_field_mask_codes','expected_loop_version','expected_remote_version_hmac_or_none','transient_title_digest_hmac_or_none','transient_body_digest_hmac_or_none','transient_due_digest_hmac_or_none','transient_reminder_time_digest_hmac_or_none','policy_version','authorization_generation','recreate_generation') 'P0-REMINDER-OPERATION-PROTOCOL-001'
Ordered @($op.durability_order) @('validate current account source loop ownership policy and authorization generations','compute operation_key_hmac without retaining readable intent','commit pending ledger entry under ADR-005 before request','revalidate account authority versions and rollback state','mark attempt_started atomically','make at most one adapter request','classify response before any retry or cursor advancement') 'P0-REMINDER-OPERATION-PROTOCOL-001'
Has ($op|ConvertTo-Json -Compress) @('zero new request','operation_key_collision','at most 3','prevent dependent cursor advancement','reconstructed from current evidence and policy','manual draft is never persisted and cannot auto-resume','remote failure never rolls it back') 'P0-REMINDER-OPERATION-PROTOCOL-001'

$rm=$m.remote_marker_protocol;Has ($rm|ConvertTo-Json -Depth 10 -Compress) @('unproven until','base32url of SHA-256','canonical operation_id bytes','remote_correlation_hmac only','no raw marker is persisted','never a title body due URL or link label','bounded complete enumeration','incomplete paging is never zero','complete_zero','complete_one','complete_many','user-assisted duplicate selection','no automatic retry','explicit user confirmation with duplicate warning','new operation identity') 'P0-REMINDER-AMBIGUOUS-WRITE-001'

