foreach($field in @('title','body','due')){$x=@($own|Where-Object{$_.origin-eq'user_authored_microsoft_artifact'-and$_.field-eq$field});if($x.Count-ne 1-or$x[0].initial-ne'user_authoritative'-or$x[0].service_update-ne'prohibited'){Fail 'P0-REMINDER-OWNERSHIP-001'}}
