Has ($m.calendar_boundary|ConvertTo-Json -Compress) @('unresolved_least_delegated_calendar_scope:G-CAL','no guessed scope or request','self-only event with zero attendees no online meeting no response request','no invitation update cancellation mail','never responds changes attendees updates deletes or cancels','zero multiple or incomplete results','no completion operation','does not support complete-MVP calendar or invitation claims') 'P0-REMINDER-CALENDAR-SAFETY-001'
Ordered @($m.review_link_boundary.prohibited) @('bearer token','pairing token','session secret','Graph or Office ID','account identifier','mailbox content','host port or URL authority','raw evidence link') 'P0-REMINDER-REVIEW-LINK-001';Has ($m.review_link_boundary|ConvertTo-Json -Compress) @('one random non-secret opaque loop handle only','authority":"none','ADR-010 authenticated per-user account-bound session','unavailable pending ADR-010 and G-ADDIN') 'P0-REMINDER-REVIEW-LINK-001'
Ordered @($m.privacy_boundary.approved_record_types) @('reminder_link','operation_ledger','user_authored_artifact_ref') 'P0-REMINDER-PRIVACY-001';Has ($m.privacy_boundary|ConvertTo-Json -Compress) @('human-readable title body due phrase reminder text or draft','raw Microsoft Graph Office account list artifact event task or URL identifier','raw remote marker request response error or authorization value','free-text conflict correction explanation or note','generic JSON map extension bag open enum unbounded string bytes array or blob','prompt model request response output rationale embedding transcript or vector','fixed non-content adapter operation reconciliation failure and count codes only','disabled') 'P0-REMINDER-PRIVACY-001'

$sd=$m.separate_decisions;if($sd.mode_semantics_eligibility_evaluation_flags_and_rollback-ne'ADR-011'-or$sd.review_link_activation_pairing_session_and_client_matrix-ne'ADR-010'-or$sd.self_email_send_recipient_and_operation_protocol-ne'ADR-013'-or$sd.storage_encryption_atomicity_and_rollback-ne'ADR-005'-or$sd.persistent_field_allowlist_and_retention-ne'ADR-PRIV-001'){Fail 'P0-REMINDER-DEFERRED-001'}
