$policy=Json $PolicyPath 'P0-REMINDER-CROSS-CONTRACT-001';if($policy.reminder_boundary.local_policy_only-ne$true){Fail 'P0-REMINDER-CROSS-CONTRACT-001'};Empty @($policy.reminder_boundary.graph_office_permissions_calls_operations) 'P0-REMINDER-CROSS-CONTRACT-001'
$evidence=Json $EvidencePath 'P0-REMINDER-CROSS-CONTRACT-001';Has ($evidence.unavailable_projection|ConvertTo-Json -Compress) @('never closes resolves dismisses or proves failure') 'P0-REMINDER-CROSS-CONTRACT-001'
