Has $threat @('Reminder adapter boundary','Durable operation first','Readable content or identifiers enter state','Remote direct edit is overwritten','Reminder controls loop lifecycle','Calendar action emails or affects another person','Review link becomes a credential','Manual draft survives a crash','Rollback, account, authorization, or version drift') 'P0-REMINDER-CROSS-CONTRACT-001'
$ids=[regex]::Matches($trace,'(?m)^\| (P0-REMINDER-[A-Z-]+-001) \|')|ForEach-Object{$_.Groups[1].Value};Exact @($ids) $checks 'P0-REMINDER-INVENTORY-001';foreach($id in $checks){if(([regex]::Matches($trace,'\b'+[regex]::Escape($id)+'\b')).Count-ne 1){Fail 'P0-REMINDER-INVENTORY-001'}}
$fresh=[regex]::Match($trace,'(?m)^\| P0-REMINDER-FRESH-CHECKER-001 \|.*$').Value;Has $fresh @('Fresh-context privacy, protocol, scope, and adversarial judges','no prompt, transcript, or model output stored','Pending closure') 'P0-REMINDER-FRESH-CHECKER-001'
if($script:fail.Count-gt 0){[Console]::Error.WriteLine(('FAIL: reminder adapter boundary: '+(($script:fail|Sort-Object)-join', ')));exit 1};if(-not$Quiet){Write-Output ('PASS: reminder adapter boundary ({0} checks; runtime, calls, permissions, records, and claims disabled)' -f $checks.Count)}
